1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  // --- Quoting: base price list -------------------------------------------
6	  it("quotes an empty item list as just the 5 G processing fee, plus 10% first-insurance surcharge — 6 G", () => {
7	    const result = runScenario({
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    });
11	
12	    expect(result).toEqual({ results: [{ premium: 6 }] });
13	  });
14	  it.todo("quotes a single sword for a long-standing customer's second contract — base 100 G");
15	  it.todo("quotes a single amulet — base 60 G");
16	  it.todo("quotes a single staff — base 80 G");
17	  it.todo("quotes a single potion — base 40 G");
18	  it.todo("quotes a single rune component — base 25 G");
19	  it.todo("quotes a single moonstone component — base 25 G");
20	  it.todo("quotes several different main items by summing their base premiums — sword + amulet = 160 G");
21	
22	  // --- Quoting: component building block -----------------------------------
23	  it.todo("quotes 3 alike components as a building block for 60 G instead of 75 G");
24	  it.todo("quotes 6 alike components as two building blocks — 120 G");
25	  it.todo("quotes 4 alike components as one building block plus one single — 85 G");
26	  it.todo("does not form a building block from 3 components of different kinds — 2 runes + 1 moonstone = 75 G");
27	
28	  // --- Quoting: risk surcharges --------------------------------------------
29	  it.todo("adds a 50% risk surcharge for a cursed item — cursed sword = 150 G");
30	  it.todo("adds a 30% risk surcharge for a highly enchanted item (enchantment >= 5) — sword at 5 = 130 G");
31	  it.todo("does not add the enchantment surcharge below level 5 — sword at 4 = 100 G");
32	  it.todo("adds both surcharges for a cursed and highly enchanted item — sword = 180 G");
33	
34	  // --- Quoting: customer modifiers -----------------------------------------
35	  it.todo("gives a 20% loyalty discount for a customer with >= 2 years — sword = 80 G");
36	  it.todo("gives no loyalty discount below 2 years with MHPCO — sword = 100 G");
37	  it.todo("adds a 10% initial assessment surcharge on the first insurance — sword = 110 G");
38	  it.todo("gives a 15% discount on each contract after the first — second quote of a sword = 85 G");
39	
40	  // --- Quoting: processing fee and rounding --------------------------------
41	  it.todo("adds the 5 G processing fee after all modifiers");
42	  it.todo("rounds the premium up, in the MHPCO's favor");
43	
44	  // --- Quoting: combinations -----------------------------------------------
45	  it.todo("combines surcharges, loyalty discount, first-insurance surcharge and fee in one quote");
46	
47	  // --- Claims: basics -------------------------------------------------------
48	  it.todo("pays a claim minus the 100 G deductible per damage event — 200 G damage pays 100 G");
49	  it.todo("pays nothing when the damage does not exceed the deductible — 100 G damage pays 0 G");
50	  it.todo("applies the deductible once per incident, not per damaged item");
51	  it.todo("reports the remaining cap after a claim — twice the insurance sum minus payout");
52	
53	  // --- Claims: reimbursement rules -----------------------------------------
54	  it.todo("reimburses damage to an item with enchantment >= 8 at 50% of the damage amount");
55	  it.todo("fully reimburses damage to an item made of dragon material");
56	  it.todo("fully reimburses dragon material even when the item is highly enchanted");
57	
58	  // --- Claims: cap ----------------------------------------------------------
59	  it.todo("caps the total payout per policy at twice the insurance sum");
60	  it.todo("reduces the remaining cap across successive claims on the same policy");
61	  it.todo("pays nothing once the cap is exhausted — remaining cap stays 0");
62	
63	  // --- Scenarios ------------------------------------------------------------
64	  it.todo("processes the spec's quote-only scenario — one result with a premium");
65	  it.todo("processes the spec's quote-then-two-claims scenario in order");
66	  it.todo("keeps separate caps for two policies of the same customer");
